package com.likerts.sdk
import kotlinx.serialization.json.JsonElement
data class SurveyProgress(val current:Int,val total:Int,val visited:Int)
private fun pages(schema:SurveySchema)=schema.pages?:listOf(SurveyPage("survey",questionIds=schema.questions.map{it.id}))
fun pageRoute(schema:SurveySchema,answers:Map<String,JsonElement>):List<Int>{val all=pages(schema);val ids=all.mapIndexed{i,p->p.id to i}.toMap();val visible=visibleAnswers(schema.questions,answers);val available=mutableSetOf<String>();val route=mutableListOf<Int>();var current=0;while(current<all.size){route+=current;available+=all[current].questionIds;val branch=all[current].branches.firstOrNull{conditionMatches(it.`when`,if(it.`when`.questionId in available)visible[it.`when`.questionId]else null)};current=branch?.let{ids[it.goToPageId]}?:current+1};return route}
fun routedAnswers(schema:SurveySchema,answers:Map<String,JsonElement>):Map<String,JsonElement>{var result=visibleAnswers(schema.questions,answers);val all=pages(schema);repeat(schema.questions.size+1){val reached=pageRoute(schema,result).flatMap{all[it].questionIds}.toSet();val filtered=visibleAnswers(schema.questions,result.filterKeys(reached::contains));if(filtered.size==result.size)return filtered;result=filtered};error("Survey route did not stabilize")}
class SurveyFlow(val schema:SurveySchema,answers:Map<String,JsonElement> = emptyMap()){private var values=routedAnswers(schema,answers);private var route=pageRoute(schema,values);private var current=route.firstOrNull()?:0;private var history=mutableListOf(current);val page get()=pages(schema)[current];val answers get()=values.toMap();val progress get()=SurveyProgress(current+1,pages(schema).size,history.size);fun setAnswer(id:String,value:JsonElement?){val old=history.toList();values=routedAnswers(schema,if(value==null)values-id else values+(id to value));route=pageRoute(schema,values);if(current !in route){var shared=route.firstOrNull()?:0;for(index in 0 until minOf(old.size,route.size)){if(old[index]!=route[index])break;shared=route[index]};current=shared};history=route.take((route.indexOf(current).takeIf{it>=0}?:0)+1).toMutableList()}fun next():Boolean{val index=route.indexOf(current);if(index<0||index+1>=route.size)return false;current=route[index+1];history=route.take(index+2).toMutableList();return true}fun back():Boolean{if(history.size<2)return false;history.removeAt(history.lastIndex);current=history.last();return true}}
